                int rw = wOff + k * c;
                int j = 0;
                for (; j < cv; j += S.length())
                    DoubleVector.fromArray(S, out, ro + j).add(DoubleVector.fromArray(S, w, rw + j).mul(aik)).intoArray(out, ro + j);
                for (; j < c; j++) out[ro + j] += aik * w[rw + j];
